# Generated by yjcli (managed - regenerated when platforms or plugins change).
# Windows counterpart of the root Makefile, same targets:
#   powershell -ExecutionPolicy Bypass -File make.ps1 <target> [NAME=<service>]
# Each target only calls tools/<tool>/<platform>/<tool>.ps1; see tools/<tool>/GUIDE.md.
param(
    [string]$Target = "help",
    [Parameter(ValueFromRemainingArguments = $true)][string[]]$Rest = @()
)
$ErrorActionPreference = "Stop"

$Platforms = "{{platforms}}".Split(" ")

function Show-Help {
    Write-Host "Usage:"
{{#if runner}}
    Write-Host "  make.ps1 <platform> [NAME=<service>]               # run locally (tools/runner)"
{{/if}}
{{#if builder}}
    Write-Host "  make.ps1 <platform>-build-<env> [NAME=<service>]   # build into dist/ (tools/builder)"
{{#if platform_proto}}
    Write-Host "  make.ps1 proto-build [PROTO_LANG=<language>]       # generate proto/dist/<language>/ (tools/builder/proto)"
{{/if}}
{{/if}}
{{#if deployer}}
    Write-Host "  make.ps1 <platform>-deploy-<env> [NAME=<service>]  # deploy dist/ (tools/deployer)"
{{/if}}
    Write-Host "  <env>: development | production | any .env.<env> under tools/secrets/<platform>/<service>/"
    Write-Host ""
    Write-Host "Platforms: $($Platforms -join ' ')"
}

$Name = ""
$Lang = ""
foreach ($arg in $Rest) {
    if ($arg -like "NAME=*") { $Name = $arg.Substring(5) }
    if ($arg -like "PROTO_LANG=*") { $Lang = $arg.Substring(11) }
}

$tool = $null
$platform = $Target
$scriptArgs = @()
{{#if builder}}
{{#if platform_proto}}
if ($Target -eq "proto-build") {
    $script = Join-Path $PSScriptRoot "tools\builder\proto\builder.ps1"
    if (-not (Test-Path $script)) {
        Write-Host "missing: tools/builder/proto/builder.ps1"
        exit 1
    }
    if ($Lang) { & $script $Lang } else { & $script }
    exit $LASTEXITCODE
}
{{/if}}
{{/if}}
{{#if builder}}
if ($Target -match "^(.+)-build-([A-Za-z0-9_-]+)$") {
    $tool = "builder"; $platform = $Matches[1]; $scriptArgs = @($Matches[2])
}
{{/if}}
{{#if deployer}}
if ($Target -match "^(.+)-deploy-([A-Za-z0-9_-]+)$") {
    $tool = "deployer"; $platform = $Matches[1]; $scriptArgs = @($Matches[2])
}
{{/if}}
{{#if runner}}
if (-not $tool -and $Platforms -contains $Target) {
    $tool = "runner"
}
{{/if}}

if ($Target -eq "help" -or -not $tool -or -not ($Platforms -contains $platform)) {
    if ($Target -ne "help") { Write-Host "Unknown target: $Target" }
    Show-Help
    if ($Target -eq "help") { exit 0 } else { exit 1 }
}

$script = Join-Path $PSScriptRoot "tools\$tool\$platform\$tool.ps1"
if (-not (Test-Path $script)) {
    Write-Host "missing: tools/$tool/$platform/$tool.ps1"
    exit 1
}
if ($Name) { $scriptArgs += $Name }
& $script @scriptArgs
exit $LASTEXITCODE
